{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Add a mild relative-frequency cue from training interactions across all four categories. Standardize log counts using only visible real items in each input history and scale their existing vectors by 1 + 0.05*tanh(z). Padding stays zero and mask-token scaling stays one. Counts persist in each model checkpoint; the generated predictor imports the updated model class and restores its buffer automatically. Learned embeddings, topology, readout, loss and optimizer remain fixed.",
      "edits": [
        {
          "find": "        self.mask_token = itemnum + 1\n        self.item_emb = nn.Embedding(itemnum + 2, hidden_units, padding_idx=0)",
          "replace": "        self.mask_token = itemnum + 1\n        self.register_buffer(\"training_item_counts\", torch.zeros(itemnum + 2))\n        self.item_emb = nn.Embedding(itemnum + 2, hidden_units, padding_idx=0)"
        },
        {
          "find": "        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)",
          "replace": "        visible = (seq > 0) & (seq <= self.itemnum)\n        log_frequency = torch.log1p(self.training_item_counts[seq])\n        visible_count = visible.sum(dim=1, keepdim=True).clamp_min(1)\n        visible_frequency = torch.where(visible, log_frequency, torch.zeros_like(log_frequency))\n        mean_frequency = visible_frequency.sum(dim=1, keepdim=True) / visible_count\n        centered = torch.where(visible, log_frequency - mean_frequency, torch.zeros_like(log_frequency))\n        variance = centered.square().sum(dim=1, keepdim=True) / visible_count\n        z = centered / (variance.sqrt() + 1e-6)\n        frequency_scale = torch.where(visible, 1.0 + 0.05 * torch.tanh(z), torch.ones_like(z))\n        item_vectors = item_vectors * frequency_scale.unsqueeze(-1)\n        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    training_counts = np.zeros(itemnum + 2, dtype=np.float32)\n    for history in user_train.values():\n        np.add.at(training_counts, np.asarray(history, dtype=np.int64), 1.0)\n    with torch.no_grad():\n        model.training_item_counts.copy_(torch.from_numpy(training_counts).to(device))\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Add checkpointed training-frequency counts and bounded history-relative input scaling to each category’s single BERT4Rec model, shared automatically with inference."
}
